public class RefCheckTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        String s = "hello";
        String t = new String("hello");
        String u = new StringBuilder("hel").append("lo").toString();

        check("same reference is the same object", true, RefCheck.sameObject(s, s));
        check("new String(...) is a different object", false, RefCheck.sameObject(s, t));
        check("...but has the same content", true, RefCheck.sameContent(s, t));
        check("StringBuilder result is a different object", false, RefCheck.sameObject(s, u));
        check("...with the same content", true, RefCheck.sameContent(s, u));
        check("two nulls have the same content", true, RefCheck.sameContent(null, null));
        check("null vs non-null differs", false, RefCheck.sameContent(null, s));
        check("non-null vs null differs (no NPE!)", false, RefCheck.sameContent(s, null));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

